# codec plugin

handle = func(origin) {
	// 编译正则表达式，`\s+` 用于匹配一个或多个连续的空白字符
	reObj, err := re.Compile(`\s+`)
	if err != nil {
		// 正则编译失败时，直接返回原文，确保程序健壮性
		return origin
	}

	// 使用正则表达式分割输入字符串，得到一个包含数字字符串的数组
	parts := reObj.Split(origin, -1)

	// 初始化一个空字符串，用于拼接最终结果
	result := ""

	// 遍历分割后的每一个部分
	for _, part := range parts {
		// 跳过因连续分隔符产生的空字符串
		if len(part) == 0 {
			continue
		}

		// 使用内置的 atoi 函数，将数字字符串转换为整数
		codePoint, err := atoi(part)
		if err != nil {
			// 如果转换失败（例如部分内容不是纯数字），则直接拼接原文
			result = result + part
			continue
		}

		// 使用 sprintf 的 "%c" 格式，将整数码点转换为对应的字符
		char := sprintf("%c", codePoint)

		// 将转换后的字符追加到结果中
		result = result + char
	}

	// 返回拼接完成的完整字符串
	return result
}
